html:
{%- set campus_display_name = frappe.db.get_value("Campus", doc.campus, "campus_name") if doc.campus else (doc.campus or "Institution of Legal Education") -%}
{%- set campus_logo_url = frappe.db.get_value("Campus", doc.campus, "logo") if doc.campus else None -%}
{%- set dob = frappe.utils.formatdate(frappe.db.get_value("Applicant", doc.applicant_id, "date_of_birth")) -%}
{%- set father_name = frappe.db.get_value("Applicant", doc.applicant_id, "father_name") -%}
{%- set mother_name = frappe.db.get_value("Applicant", doc.applicant_id, "mother_name") -%}
{%- set issue_date = frappe.utils.formatdate(frappe.utils.nowdate()) -%}

<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<title>Eligibility Result - {{ doc.applicant_id }}</title>
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
body {
font-family: "Times New Roman", Times, serif;
font-size: 13px;
background: #fff;
color: #000;
line-height: 1.4;
print-color-adjust: exact;
-webkit-print-color-adjust: exact;
}
.card-page {
width: 710px;
margin: 0 auto;
background: #fff;
border: 1.5px solid #555;
padding: 0;
position: relative;
overflow: hidden;
page-break-after: always;
}
.header {
background: #7b1c1c;
display: flex;
align-items: center;
justify-content: space-between;
padding: 10px 18px;
border-bottom: 3px solid #5a0e0e;
}
.logo-box {
width: 74px;
height: 74px;
background: #fff;
border: 2px solid rgba(255,255,255,0.6);
border-radius: 3px;
display: flex;
align-items: center; justify-content: center; flex-shrink: 0; overflow: hidden;
}
.logo-box img { max-width: 100%; max-height: 100%; object-fit: contain; }
.logo-inner {
display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
}
.logo-icon { font-size: 28px; line-height: 1; color: #7b1c1c; }
.logo-text {
font-size: 7.5px; font-weight: bold; font-family: Arial, sans-serif; color: #7b1c1c;
text-align: center; letter-spacing: 0.5px; line-height: 1.2;
}
.hdr-center { flex: 1; text-align: center; min-width: 0; padding: 0 15px; }
.univ-name {
font-size: 21px; font-weight: bold; font-family: Arial, sans-serif; color: #fff;
text-transform: none; letter-spacing: 1.2px; line-height: 1.2; margin-bottom: 0;
word-wrap: break-word; overflow-wrap: break-word;
}
.univ-sub {
font-size: 11px; font-family: Arial, sans-serif; color: rgba(255,255,255,0.80);
letter-spacing: 2.5px; text-transform: none; margin-top: 3px;
}
.title-banner {
background: #f8f8f8;
text-align: center;
padding: 12px;
border-bottom: 1.5px solid #bbb;
}
.title-banner .t1 { font-size: 15px; font-weight: bold; font-family: Arial, sans-serif; color: #7b1c1c; text-transform: none; letter-spacing: 0.5px; }
.title-banner .t2 { font-size: 13px; font-family: Arial, sans-serif; color: #444; margin-top: 4px; font-weight: bold; }

.content-wrap { padding: 15px 20px; }

.section-head {
font-family: Arial, sans-serif;
font-size: 13px;
font-weight: bold;
color: #7b1c1c;
text-transform: none;
border-bottom: 1.5px solid #7b1c1c;
padding-bottom: 4px;
margin-bottom: 10px;
margin-top: 10px;
}

.info-wrap {
border: 1.5px solid #bbb;
margin-bottom: 15px;
border-radius: 2px;
}
.info-tbl {
width: 100%;
border-collapse: collapse;
}
.info-tbl tr { border-bottom: 1px solid #ddd; }
.info-tbl tr:last-child { border-bottom: none; }
.info-tbl td {
padding: 6px 10px;
font-size: 13px;
vertical-align: middle;
line-height: 1.5;
}
.info-tbl td.lb {
font-weight: bold;
font-family: Arial, sans-serif;
width: 35%;
color: #000;
}
.info-tbl td.sp {
width: 15px;
font-weight: bold;
text-align: center;
padding: 0;
}
.info-tbl td.vl {
font-family: "Times New Roman", Times, serif;
font-weight: bold;
}

.results-table {
width: 100%;
border-collapse: collapse;
margin-top: 10px;
border: 1.5px solid #bbb;
}
.results-table th {
background: #f4f4f4;
font-family: Arial, sans-serif;
font-size: 12px;
font-weight: bold;
text-align: left;
padding: 8px 12px;
border: 1px solid #bbb;
text-transform: none;
color: #000;
}
.results-table td {
padding: 10px 12px;
font-size: 13px;
border: 1px solid #bbb;
vertical-align: middle;
}
.score-cell { font-weight: bold; font-size: 14px; }

.status-text {
font-weight: bold;
font-family: Arial, sans-serif;
font-size: 13px;
color: #000;
}

.disclaimer {
margin-top: 20px;
padding: 12px;
background: #fff;
border: 1px solid #ddd;
border-radius: 2px;
font-family: Arial, sans-serif;
font-size: 11.5px;
line-height: 1.5;
color: #333;
}

.footer {
margin-top: 25px;
border-top: 1px solid #ddd;
padding-top: 10px;
display: flex;
justify-content: space-between;
font-family: Arial, sans-serif;
font-size: 9.5px;
color: #555;
}
</style>
</head>
<body>
<div class="card-page">
<div class="header">
  <div class="logo-box">
    {% if campus_logo_url %}
      <img src="{{ campus_logo_url }}" alt="Campus Logo">
    {% else %}
      <div class="logo-inner"><span class="logo-icon">⚖</span><span class="logo-text">Law<br>School</span></div>
    {% endif %}
  </div>
  <div class="hdr-center">
    <div class="univ-name">{{ campus_display_name }}</div>
    <div class="univ-sub">Office of Admissions &nbsp;&middot;&nbsp; Eligibility Cell</div>
  </div>
  <div class="logo-box" style="visibility:hidden; border:none; background:transparent;"></div>
</div>
<div class="title-banner">
<div class="t1">Eligibility Result Mark Sheet</div>
<div class="t2">Academic Year: {{ doc.academic_year or "—" }} &nbsp;&middot;&nbsp; Admission Cycle: {{ doc.admission_cycle or "—" }}</div>
</div>

<div class="content-wrap">
<div class="section-head">Candidate Details</div>
<div class="info-wrap">
  <table class="info-tbl">
    <tbody>
      <tr><td class="lb">Candidate Name</td><td class="sp">:</td><td class="vl">{{ doc.candidate_name or "—" }}</td></tr>
      <tr><td class="lb">Application Number</td><td class="sp">:</td><td class="vl">{{ doc.applicant_id or "—" }}</td></tr>
      <tr><td class="lb">Date of Birth</td><td class="sp">:</td><td class="vl">{{ dob or "—" }}</td></tr>
      <tr><td class="lb">Gender</td><td class="sp">:</td><td class="vl">{{ doc.gender or "—" }}</td></tr>
      <tr><td class="lb">Father's Name</td><td class="sp">:</td><td class="vl">{{ father_name or "—" }}</td></tr>
      <tr><td class="lb">Mother's Name</td><td class="sp">:</td><td class="vl">{{ mother_name or "—" }}</td></tr>
    </tbody>
  </table>
</div>

<div class="section-head">Programme Details</div>
<div class="info-wrap">
  <table class="info-tbl">
    <tbody>
      <tr><td class="lb">Programme</td><td class="sp">:</td><td class="vl">{{ doc.program or "—" }}</td></tr>
      <tr><td class="lb">Campus</td><td class="sp">:</td><td class="vl">{{ doc.campus or "—" }}</td></tr>
    </tbody>
  </table>
</div>

<div class="section-head">Assessment Result</div>
<table class="results-table">
<thead>
<tr>
  <th>Assessment Component</th>
  <th>Maximum Marks</th>
  <th>Marks Obtained</th>
</tr>
</thead>
<tbody>
<tr>
  <td>Entrance Test Score</td>
  <td>100</td>
  <td class="score-cell">{{ doc.entrance_test_score or 0 }}</td>
</tr>
<tr>
  <td>Interview Assessment Score</td>
  <td>100</td>
  <td class="score-cell">{{ doc.interview_score or 0 }}</td>
</tr>
<tr style="background: #f9f9f9;">
  <td colspan="2" style="text-align: right; font-weight: bold; font-family: Arial, sans-serif; font-size: 12px;">Result Status</td>
  <td>
    <span class="status-text">{{ doc.result_status or "—" }}</span>
  </td>
</tr>
</tbody>
</table>

<div class="disclaimer">
<strong>Important:</strong> This document is a system-generated mark sheet. 
It reflects the eligibility assessment based on the scores obtained by the candidate. 
Final admission is subject to verification of original documents and fulfillment of all criteria. 
Errors and omissions are excepted.
</div>

<div class="footer">
<div>
Reference: <strong>{{ doc.name }}</strong><br>
Generated on: <strong>{{ issue_date }}</strong><br>
Source Type: {{ doc.source_type or "—" }}
</div>
<div style="text-align: right;">
Authorized Signatory<br>
(Digitally Verified Document)
</div>
</div>
<div style="text-align: center; margin-top: 10px; color: #aaa; font-size: 10px;">
    *************
</div>
</div>
</div>
</body>
</html>
